-- Ledgr demo data: Tropic Press Juices (generated by scripts/seed.ts, exported with pg_dump).
-- Loads into a database that already has migrations 0001-0010. Triggers are paused while loading
-- because the rows are already posted (FIFO costs, audit trail) and must be copied exactly.
do $d$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I disable trigger user', t); end loop; end $d$;
SELECT pg_catalog.setval('public.audit_log_id_seq', 4121, true);
do $d$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable trigger user', t); end loop; end $d$;
select setval(pg_get_serial_sequence('public.audit_log', 'id'), (select coalesce(max(id), 1) from public.audit_log));
